"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[5738],{1922(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome-to-camera-parameters-blog","metadata":{"permalink":"/AndroidCameraParameters/es/blog/welcome-to-camera-parameters-blog","editUrl":"https://github.com/zoozooll/AndroidCameraParameters/tree/main/website/blog/2026-08-23-welcome.mdx","source":"@site/blog/2026-08-23-welcome.mdx","title":"Welcome to the Android Camera Parameters Blog","description":"Welcome to the official blog for Android Camera Parameters!","date":"2026-08-23T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/AndroidCameraParameters/es/blog/tags/release","description":"Announcements about new versions and features."},{"inline":false,"label":"Tutorial","permalink":"/AndroidCameraParameters/es/blog/tags/tutorial","description":"Step-by-step guides for using the tool."}],"readingTime":0.97,"hasTruncateMarker":true,"authors":[{"name":"zoozooll","title":"Maintainer of Android Camera Parameters","url":"https://github.com/zoozooll","imageURL":"https://github.com/zoozooll.png","key":"zoozooll","page":null}],"frontMatter":{"slug":"welcome-to-camera-parameters-blog","title":"Welcome to the Android Camera Parameters Blog","authors":["zoozooll"],"tags":["release","tutorial"]},"unlisted":false},"content":"Welcome to the official blog for **Android Camera Parameters**!\\n\\nThis blog will be the home for updates, tutorials, and deep dives into the Android Camera2 API.\\n\\n{/* truncate */}\\n\\n## Why we built this tool\\n\\nAndroid Camera2 API is powerful but complex. Developers often struggle to understand what a specific device\'s camera can actually do. Our tool aims to make this information accessible and easy to understand.\\n\\n### Visualizing Camera Capabilities\\n\\nYou can inspect sensor details, lens characteristics, and hardware levels for all cameras on your device.\\n\\n![App Screenshot](/img/camera_params_screen_overview.png)\\n\\n## Multimedia Features\\n\\nDocusaurus allows us to embed various media types. For example, here is a placeholder for a future video tutorial:\\n\\n<div className=\\"video-container\\">\\n  <iframe\\n    width=\\"100%\\"\\n    height=\\"400\\"\\n    src=\\"https://www.youtube.com/embed/dQw4w9WgXcQ\\"\\n    title=\\"YouTube video player\\"\\n    frameBorder=\\"0\\"\\n    allow=\\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\\"\\n    allowFullScreen\\n  ></iframe>\\n</div>\\n\\n## Technical Deep Dive (Coming Soon)\\n\\nWe will use the `camera2` tag for posts that explore technical aspects like:\\n- **Stream Configurations**: Understanding which resolutions and formats are supported.\\n- **Hardware Level**: What `LEGACY` vs `FULL` vs `LEVEL_3` really means.\\n- **Physical vs Logical Cameras**: Navigating the multi-camera era.\\n\\nStay tuned for more updates!"}]}}')}}]);